    var keys = ['m', 'a', 'n'], rate = keys.map(function (s) { return sh[s] / DM.shiftProd[s] * 100; }), mx = Math.max.apply(null, rate), lab = 170, mr = 150, rh = 46, H = keys.length * rh + 6, pw = W0 - lab - mr, g = '';
